#!/usr/bin/env python3
"""Run C2 Unit07 recalibration with target-safe C2 length margin."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c2_unit07.py')
text=SOURCE.read_text(encoding='utf-8')
marker='UPDATES={'
assert text.count(marker)==1
EXTRA={
'ar-c2-u07-p02':"""وفي مراجعة أخيرة طلبت الباحثة من فريق مستقل ترتيب قوة التفسيرات من دون رؤية أسماء الطبعات. أعطاهم ملف المصدر، وبيانات الجمهور، وسجل التحرير، ثم جعلهم يذكرون لكل فرضية دليلاً يرفع وزنها ودليلاً قد يضعفها. اتضح أن بعض الفروق التي بدت أولًا سمات في الكاتب تفسرها تعليمات النشر بصورة أفضل، بينما بقيت فروق أخرى بلا سبب حاسم. سجل الفريق هذه البقايا بوصفها مسائل مفتوحة بدل ملئها بقصة نفسية عن صاحب النص. بهذه الطريقة صار تاريخ النقل أداة لتوزيع الثقة بين الأسباب الممكنة، لا ذريعة لإزالة كل عدم حسم أو لإسناد كل فرق إلى مصدر واحد.""",
'ar-c2-u07-p03':"""وفي تمرين آخر أخفى الفريق عناوين النسخ وأعطى الطلاب الأحداث والأصوات فقط. طلب منهم صياغة قراءتين متعارضتين ثم ذكر التفصيل الذي يضغط على كل واحدة. عندما كُشفت الخلفية الثقافية لاحقًا، زادت قوة بعض الروابط لكنها لم تلغ المواد المخالفة. استخدم الفريق هذا التدرج لتعليم الفرق بين إثراء القراءة وإغلاقها. كما طلب من الطلاب حذف حدث واحد في كل مرة ورؤية ما إذا بقي التفسير يعمل بالقوة نفسها. الحدث الذي يؤدي حذفُه إلى انهيار الحجة يحمل وزنًا مختلفًا عن تفصيل يمكن الاستغناء عنه. بهذه الطريقة أصبحت البنية الداخلية معيارًا يوازن المعرفة الخارجية بدل أن تخضع لها بالكامل.""",
'ar-c2-u07-p04':"""ثم أعاد فريق خارجي بناء منطق العرض من المشاهدة وحدها، فحدد علاقة الاعتماد وحدود السلطة لكنه لم يفهم سبب بقاء الطقس القديم في المشهد الأوسط. عاد المخرج إلى تلك النقطة ووجد أن الشرح داخل الحوار كان متأخرًا إلى درجة جعل الفعل يبدو زخرفيًا قبل انكشاف وظيفته. نقل إشارة صغيرة إلى وقت أبكر من دون إضافة محاضرة، فتحسن فهم الرهان في الاختبار التالي. أظهر ذلك أن الحفاظ على عنصر قديم لا ينجح بمجرد وجوده على الخشبة؛ يجب أن يجد مكانًا وظيفيًا داخل النسخة الجديدة يسمح للجمهور ببناء علاقته بالأحداث في الوقت المناسب.""",
'ar-c2-u07-p05':"""وفي اختبار منفصل غيّر الفريق نوع الأداء مع إبقاء الكلمات ثابتة. عندما أدى شخص واحد جميع الشخصيات احتاج النص إلى إشارات أوضح عند الانتقال، بينما خف هذا العبء مع عدة ممثلين. سجل الفريق لذلك نسختين من النص لا نسخة واحدة مطلقة. كما اختبروا مواضع الضوضاء الخلفية، فوجدوا أن معلومة قصيرة يمكن أن تضيع إذا جاءت فوق مؤثر قوي رغم وضوحها لغويًا. نقلوا المعلومة إلى لحظة أهدأ بدل رفع الصوت فقط. كشف المثال أن نجاح النقل يعتمد على البيئة الإدراكية الفعلية، وأن التحرير يحتاج إلى معرفة ما الذي ينافس الانتباه في كل لحظة لا إلى عدد الكلمات وحده.""",
'ar-c2-u07-p06':"""وفي مراجعة ختامية طلبت اللجنة من كل فريق اختيار قرار واحد اختلف حوله الأعضاء وكتابة سجل قصير يبين البدائل التي رفضوها ولماذا. ظهر أن بعض الخلافات تتعلق بما يجب حفظه، وبعضها بما يستطيع الوسيط حمله، وبعضها بتوقعات عن الجمهور لم تُختبر بعد. عندما فرزوا هذه الأسباب صار من الممكن حل بعضها بتجربة صغيرة وترك بعضها بوصفه اختيارًا فنيًا معلنًا. لم تعد كلمة «أمانة» تنهي النقاش؛ أصبحت اسمًا لحزمة من الالتزامات يمكن توزيعها وفحصها بحسب نوع المشروع، مع الاعتراف بأن بعض المفاضلات لا تختفي حتى بعد أفضل تحليل متاح.""",
}
extra_code="EXTRA = "+repr(EXTRA)+"\nfor _pid,_extra in EXTRA.items():\n    ADD[_pid]=ADD[_pid].rstrip()+' '+_extra.strip()\n"
patched=text.replace(marker,extra_code+'\n'+marker,1)
exec(compile(patched,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
